import { ApiError } from '@/api/client';
import { ErrorBlock } from '@/components/system/error_block';
import { SectionNav } from '@/components/system/section_nav';
import { StubBanner } from '@/components/system/stub_banner';
import type { SectionNavItem } from '@/lib/nav_config';

export const AUTOMATION_NAV_ITEMS: SectionNavItem[] = [
  { path: '/automation', label: 'Hub', exact: true },
  { path: '/automation/presets', label: 'Automation presets' },
  { path: '/automation/rules', label: 'Automation rules' },
  { path: '/traffic-optimizer/presets', label: 'Optimizer presets' },
  { path: '/traffic-optimizer/rules', label: 'Optimizer rules' },
  { path: '/smart-alerts/rules', label: 'Alert rules' },
  { path: '/smart-alerts/history', label: 'Alert history' },
  { path: '/margin-guard/policies', label: 'Margin policies' },
  { path: '/margin-guard/activity', label: 'Margin activity' },
];

export function AutomationNav() {
  return <SectionNav items={AUTOMATION_NAV_ITEMS} label="Automation sections" />;
}

export function automationPanelError(error: Error, title: string) {
  if (error instanceof ApiError && error.status === 501) {
    return <StubBanner title={`${title} unavailable`} message={error.message} />;
  }
  return <ErrorBlock title={title} message={error.message} />;
}
