import { Link } from 'react-router-dom';

import { FilterApplyButton } from '@/components/system/action_buttons';
import {
  DirectoryTable,
  DirectoryTableHead,
  TableBody,
  TableCell,
  TableHeader,
  TableRow,
} from '@/components/system/directory_table';
import {
  DirectoryFilterForm,
  FilterField,
  FilterPanel,
} from '@/components/system/filter_panel';
import { PageChrome } from '@/components/system/page_chrome';
import { PaginationPrevNext } from '@/components/system/pagination_prev_next';
import { Badge } from '@/components/ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { EmptyState } from '@/components/system/empty_state';
import { ErrorBlock } from '@/components/system/error_block';
import { PageSkeleton } from '@/components/system/page_skeleton';
import type { Customer } from '@/api/types';
import { displayTimestamp } from '@/lib/display';

export type CustomerSortField = 'name' | 'created_at';
export type SortOrder = 'asc' | 'desc';

export type CustomersDirectoryProps = {
  items: Customer[];
  total: number;
  limit: number;
  offset: number;
  draftSort: CustomerSortField;
  draftOrder: SortOrder;
  fetching: boolean;
  error: Error | undefined;
  hasSnapshot: boolean;
  freshnessLabel?: string;
  onDraftSortChange: (sort: CustomerSortField) => void;
  onDraftOrderChange: (order: SortOrder) => void;
  onApplyFilters: () => void;
  onPageChange: (nextOffset: number) => void;
};

export function CustomersDirectory({
  items,
  total,
  limit,
  offset,
  draftSort,
  draftOrder,
  fetching,
  error,
  hasSnapshot,
  freshnessLabel,
  onDraftSortChange,
  onDraftOrderChange,
  onApplyFilters,
  onPageChange,
}: CustomersDirectoryProps) {
  if (fetching && !hasSnapshot && !error) {
    return <PageSkeleton variant="directory" columns={4} />;
  }

  if (error && !hasSnapshot) {
    return <ErrorBlock title="Could not load customers" message={error.message} />;
  }

  const canGoPrev = offset > 0;
  const canGoNext = offset + limit < total;

  return (
    <PageChrome
      title="Customers"
      badge={
        freshnessLabel ? (
          <Badge variant="secondary">{freshnessLabel}</Badge>
        ) : undefined
      }
    >
      <FilterPanel>
        <DirectoryFilterForm
          onSubmit={(event) => {
            event.preventDefault();
            onApplyFilters();
          }}
        >
          <FilterField htmlFor="customers-sort" label="Sort">
            <Select
              value={draftSort}
              onValueChange={(value) => onDraftSortChange(value as CustomerSortField)}
            >
              <SelectTrigger id="customers-sort" className="h-9 w-full text-sm">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="name">Name</SelectItem>
                <SelectItem value="created_at">Created</SelectItem>
              </SelectContent>
            </Select>
          </FilterField>

          <FilterField htmlFor="customers-order" label="Order">
            <Select
              value={draftOrder}
              onValueChange={(value) => onDraftOrderChange(value as SortOrder)}
            >
              <SelectTrigger id="customers-order" className="h-9 w-full text-sm">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="asc">Ascending</SelectItem>
                <SelectItem value="desc">Descending</SelectItem>
              </SelectContent>
            </Select>
          </FilterField>

          <FilterApplyButton disabled={fetching}>Apply</FilterApplyButton>

          <PaginationPrevNext
            canGoPrev={canGoPrev}
            canGoNext={canGoNext}
            disabled={fetching}
            onPrev={() => onPageChange(Math.max(0, offset - limit))}
            onNext={() => onPageChange(offset + limit)}
          />
        </DirectoryFilterForm>
      </FilterPanel>

      <div aria-atomic="true" aria-live="polite">
      {items.length === 0 ? (
        <EmptyState
          variant="blank-slate"
          title="No customers"
          description="Customers are provisioned through billing and platform setup."
          actionLabel="View documentation"
          actionHref="/docs"
        />
      ) : (
        <DirectoryTable>
          <TableHeader>
            <TableRow>
              <DirectoryTableHead>Name</DirectoryTableHead>
                <DirectoryTableHead>Balance</DirectoryTableHead>
                <DirectoryTableHead>Currency</DirectoryTableHead>
                <DirectoryTableHead>Cost center</DirectoryTableHead>
                <DirectoryTableHead>Active campaigns</DirectoryTableHead>
                <DirectoryTableHead>Total spend</DirectoryTableHead>
                <DirectoryTableHead>Created</DirectoryTableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {items.map((customer) => (
                <TableRow key={customer.id ?? customer.name}>
                  <TableCell className="font-medium">
                    {customer.id ? (
                      <Link className="text-primary hover:underline" to={`/customers/${customer.id}`}>
                        {customer.name ?? customer.id}
                      </Link>
                    ) : (
                      customer.name
                    )}
                  </TableCell>
                  <TableCell className="tabular-nums">{customer.balance ?? ''}</TableCell>
                  <TableCell>{customer.currency ?? ''}</TableCell>
                  <TableCell>{customer.cost_center ?? ''}</TableCell>
                  <TableCell className="tabular-nums">{customer.active_campaigns ?? ''}</TableCell>
                  <TableCell className="tabular-nums">{customer.total_spend ?? ''}</TableCell>
                  <TableCell>
                    {displayTimestamp(customer.created_at, customer.created_at_display)}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
        </DirectoryTable>
      )}
      </div>
    </PageChrome>
  );
}
