import { Link } from 'react-router-dom';

import { PageChrome } from '@/components/system/page_chrome';
import { ErrorBlock } from '@/components/system/error_block';
import { PageSkeleton } from '@/components/system/page_skeleton';
import { StubBanner } from '@/components/system/stub_banner';
import { Button } from '@/components/ui/button';
import { DatetimePicker } from '@/components/ui/datetime_picker';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { DASHBOARD_ROLES, formatDashboardRoleLabel } from '@/api/dashboards_api';
import type { DashboardRole } from '@/api/types';
import { JsonDashboardView } from '@/domains/dashboards/json_dashboard_view';

export type RoleDashboardViewProps = {
  role: DashboardRole;
  draftRole: DashboardRole;
  draftCustomerId: string;
  draftFrom: string;
  draftTo: string;
  payload: Record<string, unknown> | undefined;
  fetching: boolean;
  error: Error | undefined;
  hasSnapshot: boolean;
  licenseGated: boolean;
  onDraftRoleChange: (role: DashboardRole) => void;
  onDraftCustomerIdChange: (value: string) => void;
  onDraftFromChange: (value: string) => void;
  onDraftToChange: (value: string) => void;
  onApply: () => void;
};

export function RoleDashboardView({
  role,
  draftRole,
  draftCustomerId,
  draftFrom,
  draftTo,
  payload,
  fetching,
  error,
  hasSnapshot,
  licenseGated,
  onDraftRoleChange,
  onDraftCustomerIdChange,
  onDraftFromChange,
  onDraftToChange,
  onApply,
}: RoleDashboardViewProps) {
  if (fetching && !hasSnapshot && !error) {
    return <PageSkeleton />;
  }

  if (licenseGated) {
    return (
      <PageChrome title="Dashboards">
        <StubBanner
          title="License required"
          message="This dashboard is not available on the current license tier."
        />
      </PageChrome>
    );
  }

  if (error && !hasSnapshot) {
    return <ErrorBlock title={`Could not load ${formatDashboardRoleLabel(role)} dashboard`} message={error.message} />;
  }

  return (
    <PageChrome title={`${formatDashboardRoleLabel(role)} dashboard`}>
      <div className="grid grid-cols-[repeat(auto-fill,minmax(12rem,1fr))] items-end gap-4">
        <div className="grid gap-2">
          <Label htmlFor="dashboard-role">Role</Label>
          <Select value={draftRole} onValueChange={(value) => onDraftRoleChange(value as DashboardRole)}>
            <SelectTrigger id="dashboard-role">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {DASHBOARD_ROLES.map((item) => (
                <SelectItem key={item} value={item}>
                  {formatDashboardRoleLabel(item)}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
        <div className="grid gap-2">
          <Label htmlFor="dashboard-customer-id">Customer ID</Label>
          <Input
            id="dashboard-customer-id"
            value={draftCustomerId}
            onChange={(event) => onDraftCustomerIdChange(event.target.value)}
          />
        </div>
        <DatetimePicker
          id="dashboard-from"
          label="From"
          value={draftFrom}
          onChange={onDraftFromChange}
        />
        <DatetimePicker id="dashboard-to" label="To" value={draftTo} onChange={onDraftToChange} />
        <Button disabled={fetching || !draftCustomerId.trim()} onClick={onApply} type="button">
          Load
        </Button>
      </div>

      <div className="text-sm text-muted-foreground">
        <Link className="hover:underline" to="/rtb">
          RTB overview
        </Link>
      </div>

      {payload ? <JsonDashboardView payload={payload} /> : null}

      {error && hasSnapshot ? <ErrorBlock title="Refresh failed" message={error.message} /> : null}
    </PageChrome>
  );
}
