import type { ReactNode } from 'react';
import { Link } from 'react-router-dom';

import { cn } from '@/lib/utils';

export type HubLinkItem = {
  path: string;
  title: string;
  description: string;
};

export function HubLinkGrid({
  children,
  className,
}: {
  children: ReactNode;
  className?: string;
}) {
  return (
    <div
      className={cn(
        'grid gap-4 sm:grid-cols-[repeat(auto-fit,minmax(280px,1fr))]',
        className,
      )}
    >
      {children}
    </div>
  );
}

export function HubLinkCard({ path, title, description }: HubLinkItem) {
  return (
    <Link
      className="ui-surface-raised group flex h-full flex-col gap-3 p-5 transition-colors hover:bg-muted/30"
      to={path}
    >
      <div className="grid gap-1.5">
        <h3 className="text-base font-medium tracking-tight group-hover:underline">{title}</h3>
        <p className="text-sm leading-relaxed text-muted-foreground">{description}</p>
      </div>
      <span className="mt-auto text-xs text-muted-foreground">Open</span>
    </Link>
  );
}
