import { useMemo } from 'react';

import { FilterApplyButton, PrimaryActionButton } from '@/components/system/action_buttons';
import { ErrorBlock } from '@/components/system/error_block';
import { FilterField, FilterPanel } from '@/components/system/filter_panel';
import { PageChrome } from '@/components/system/page_chrome';
import { PageSkeleton } from '@/components/system/page_skeleton';
import { PanelSection, StatPanel, StatRow } from '@/components/system/stat_panel';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { COLD_PATH_MAX_BODY_CHARS } from '@/lib/body_limits';
import { settingsFieldLabel } from '@/lib/settings_labels';
import {
  settingsBoolValue,
  settingsEmptyValue,
  settingsMonoValue,
  settingsTextValue,
} from '@/domains/settings/settings_empty';
import { SettingsAppearancePanel } from '@/domains/settings/settings_appearance_panel';
import { SettingsNav } from '@/domains/settings/settings_nav';
import { parsePlatformSettingsSnapshot } from '@/domains/settings/settings_snapshot';

export type PlatformSettingsProps = {
  payload: Record<string, unknown> | undefined;
  draftPatchJson: string;
  draftInstallRoot: string;
  draftInstallToken: string;
  draftBootstrapJson: string;
  fetching: boolean;
  patching: boolean;
  applying: boolean;
  bootstrapping: boolean;
  error: Error | undefined;
  patchError: Error | undefined;
  applyError: Error | undefined;
  bootstrapError: Error | undefined;
  patchSuccess: boolean;
  applySuccess: boolean;
  bootstrapSuccess: boolean;
  applyWrittenPath: string | undefined;
  hasSnapshot: boolean;
  restartRequired: boolean;
  showBootstrap: boolean;
  onDraftPatchJsonChange: (value: string) => void;
  onDraftInstallRootChange: (value: string) => void;
  onDraftInstallTokenChange: (value: string) => void;
  onDraftBootstrapJsonChange: (value: string) => void;
  onApplyPatch: () => void;
  onApplyToDisk: () => void;
  onRunBootstrap: () => void;
};

export function PlatformSettings({
  payload,
  draftPatchJson,
  draftInstallRoot,
  draftInstallToken,
  draftBootstrapJson,
  fetching,
  patching,
  applying,
  bootstrapping,
  error,
  patchError,
  applyError,
  bootstrapError,
  patchSuccess,
  applySuccess,
  bootstrapSuccess,
  applyWrittenPath,
  hasSnapshot,
  restartRequired,
  showBootstrap,
  onDraftPatchJsonChange,
  onDraftInstallRootChange,
  onDraftInstallTokenChange,
  onDraftBootstrapJsonChange,
  onApplyPatch,
  onApplyToDisk,
  onRunBootstrap,
}: PlatformSettingsProps) {
  const snapshot = useMemo(
    () => (payload ? parsePlatformSettingsSnapshot(payload) : undefined),
    [payload],
  );

  if (fetching && !hasSnapshot && !error) {
    return <PageSkeleton />;
  }

  if (error && !hasSnapshot) {
    return <ErrorBlock title="Could not load platform settings" message={error.message} />;
  }

  return (
    <PageChrome
      title="Platform settings"
      description="Active platform configuration, secrets metadata, and persistence actions."
      badge={
        restartRequired ? (
          <Badge variant="secondary">Restart required</Badge>
        ) : snapshot?.bootstrapComplete ? (
          <Badge variant="outline">Live</Badge>
        ) : undefined
      }
    >
      <SettingsNav />

      <SettingsAppearancePanel />

      {showBootstrap ? (
        <PanelSection title="Initial setup">
          <FilterPanel className="rounded-none border-0 bg-transparent">
            <p className="text-sm text-muted-foreground sm:col-span-2">
              Create the platform configuration on first run using the setup token from your
              deployment bundle.
            </p>
            <FilterField htmlFor="settings-install-token" label="Setup token">
              <Input
                id="settings-install-token"
                type="password"
                autoComplete="off"
                value={draftInstallToken}
                onChange={(event) => onDraftInstallTokenChange(event.target.value)}
              />
            </FilterField>
            <FilterField
              className="sm:col-span-2"
              htmlFor="settings-bootstrap-json"
              label="Setup configuration"
            >
              <Textarea
                id="settings-bootstrap-json"
                className="min-h-[10rem] font-mono text-xs"
                value={draftBootstrapJson}
                maxLength={COLD_PATH_MAX_BODY_CHARS}
                onChange={(event) => onDraftBootstrapJsonChange(event.target.value)}
                placeholder={'{\n  "admin_email": "ops@example.com",\n  "admin_password": "change-me",\n  "config": {\n    "tracking_domain": "track.example.com"\n  }\n}'}
              />
            </FilterField>
            <div className="flex flex-wrap items-center gap-3 sm:col-span-2">
              <PrimaryActionButton
                disabled={bootstrapping || !draftInstallToken.trim() || !draftBootstrapJson.trim()}
                loading={bootstrapping}
                onClick={onRunBootstrap}
                type="button"
              >
                {bootstrapping ? 'Setting up...' : 'Complete setup'}
              </PrimaryActionButton>
              {bootstrapSuccess ? (
                <p className="text-sm text-muted-foreground" role="status">
                  Initial setup completed.
                </p>
              ) : null}
            </div>
            {bootstrapError ? (
              <div className="sm:col-span-2">
                <ErrorBlock title="Setup failed" message={bootstrapError.message} />
              </div>
            ) : null}
          </FilterPanel>
        </PanelSection>
      ) : null}

      {snapshot ? (
        <>
          {snapshot.restartPending.length > 0 ? (
            <PanelSection
              meta={<Badge variant="secondary">{snapshot.restartPending.length} pending</Badge>}
              title="Pending restart"
            >
              <ul className="list-disc space-y-1 px-5 pb-5 pl-10 text-sm text-muted-foreground">
                {snapshot.restartPending.map((field) => (
                  <li key={field}>{settingsFieldLabel(field)}</li>
                ))}
              </ul>
            </PanelSection>
          ) : null}

          <div className="grid gap-4 lg:grid-cols-[repeat(auto-fit,minmax(280px,1fr))]">
            <StatPanel
              meta={
                snapshot.bootstrapComplete ? (
                  <Badge variant="outline">Ready</Badge>
                ) : (
                  <Badge variant="secondary">Pending</Badge>
                )
              }
              title="Platform status"
            >
              <StatRow
                label={settingsFieldLabel('bootstrap_complete')}
                value={snapshot.bootstrapComplete ? 'Complete' : 'Pending'}
              />
              <StatRow
                label={settingsFieldLabel('profile')}
                value={settingsTextValue(snapshot.config.profile, 'profile')}
              />
              <StatRow
                label={settingsFieldLabel('telemetry_enabled')}
                value={settingsBoolValue(snapshot.config.telemetryEnabled, 'telemetry_enabled')}
              />
            </StatPanel>

            <StatPanel title="Tracking and ingress">
              <StatRow
                label={settingsFieldLabel('tracking_domain')}
                value={settingsTextValue(snapshot.config.trackingDomain, 'tracking_domain')}
              />
              <StatRow
                label={settingsFieldLabel('ingress_schema')}
                value={settingsTextValue(snapshot.config.ingressSchema, 'ingress_schema')}
              />
              <StatRow
                label={settingsFieldLabel('default_currency')}
                value={settingsTextValue(snapshot.config.defaultCurrency, 'default_currency')}
              />
              <StatRow
                label={settingsFieldLabel('timezone')}
                value={settingsTextValue(snapshot.config.timezone, 'timezone')}
              />
            </StatPanel>

            <StatPanel title="Edge">
              <StatRow
                label={settingsFieldLabel('edge_xdp')}
                value={settingsBoolValue(snapshot.config.edgeXdp, 'edge_xdp')}
              />
              <StatRow
                label={settingsFieldLabel('edge_expose_click')}
                value={settingsBoolValue(snapshot.config.edgeExposeClick, 'edge_expose_click')}
              />
              <StatRow
                label={settingsFieldLabel('edge_expose_openrtb')}
                value={settingsBoolValue(snapshot.config.edgeExposeOpenRTB, 'edge_expose_openrtb')}
              />
              <StatRow
                label={settingsFieldLabel('network_interface')}
                value={settingsTextValue(snapshot.config.networkInterface, 'network_interface')}
              />
            </StatPanel>
          </div>

          <div className="grid gap-4 lg:grid-cols-2">
            <PanelSection title="URL templates">
              <dl className="grid gap-4 px-5 py-4 text-sm">
                <div className="grid gap-1">
                  <dt className="text-muted-foreground">{settingsFieldLabel('click_url_template')}</dt>
                  <dd className="break-all font-mono text-xs">
                    {settingsMonoValue(snapshot.clickUrlTemplate, 'click_url_template')}
                  </dd>
                </div>
                <div className="grid gap-1">
                  <dt className="text-muted-foreground">
                    {settingsFieldLabel('openrtb_endpoint_template')}
                  </dt>
                  <dd className="break-all font-mono text-xs">
                    {settingsMonoValue(snapshot.openRtbEndpointTemplate, 'openrtb_endpoint_template')}
                  </dd>
                </div>
              </dl>
            </PanelSection>

            <PanelSection title="Secrets">
              <dl className="grid gap-3 px-5 py-4 text-sm">
                <div className="flex justify-between gap-4">
                  <dt className="text-muted-foreground">{settingsFieldLabel('stripe_secret_key')}</dt>
                  <dd className="font-mono text-xs tabular-nums">
                    {settingsMonoValue(snapshot.secrets.stripeSecretKey, 'stripe_secret_key')}
                  </dd>
                </div>
                <div className="flex justify-between gap-4">
                  <dt className="text-muted-foreground">
                    {settingsFieldLabel('stripe_webhook_secret')}
                  </dt>
                  <dd className="font-mono text-xs tabular-nums">
                    {settingsMonoValue(snapshot.secrets.stripeWebhookSecret, 'stripe_webhook_secret')}
                  </dd>
                </div>
              </dl>
            </PanelSection>
          </div>

          <PanelSection title="Stripe checkout">
            <dl className="grid gap-3 px-5 py-4 text-sm">
              <div className="flex justify-between gap-4">
                <dt className="text-muted-foreground">{settingsFieldLabel('stripe_enabled')}</dt>
                <dd className="tabular-nums">
                  {settingsBoolValue(snapshot.config.stripeEnabled, 'stripe_enabled')}
                </dd>
              </div>
              <div className="grid gap-1">
                <dt className="text-muted-foreground">
                  {settingsFieldLabel('stripe_checkout_success_url')}
                </dt>
                <dd className="break-all font-mono text-xs">
                  {settingsMonoValue(
                    snapshot.config.stripeCheckoutSuccessUrl,
                    'stripe_checkout_success_url',
                  )}
                </dd>
              </div>
              <div className="grid gap-1">
                <dt className="text-muted-foreground">
                  {settingsFieldLabel('stripe_checkout_cancel_url')}
                </dt>
                <dd className="break-all font-mono text-xs">
                  {settingsMonoValue(
                    snapshot.config.stripeCheckoutCancelUrl,
                    'stripe_checkout_cancel_url',
                  )}
                </dd>
              </div>
            </dl>
          </PanelSection>

          <details className="ui-surface-raised group">
            <summary className="cursor-pointer list-none px-5 py-4 text-base font-medium tracking-tight marker:content-none [&::-webkit-details-marker]:hidden">
              Raw configuration payload
            </summary>
            <pre className="ui-code-block mx-5 mb-5 max-h-96 overflow-auto text-xs">
              {JSON.stringify(payload, null, 2)}
            </pre>
          </details>
        </>
      ) : null}

      <PanelSection title="Update configuration">
        <FilterPanel className="rounded-none border-0 bg-transparent">
          <p className="text-sm text-muted-foreground sm:col-span-2">
            Apply partial updates to the active platform configuration. Changes take effect in
            memory; use save to disk when you need a persistent install bundle.
          </p>
          <FilterField
            className="sm:col-span-2"
            htmlFor="settings-patch-json"
            label="Configuration changes"
          >
            <Textarea
              id="settings-patch-json"
              className="min-h-[8rem] font-mono text-xs"
              value={draftPatchJson}
              maxLength={COLD_PATH_MAX_BODY_CHARS}
              onChange={(event) => onDraftPatchJsonChange(event.target.value)}
              placeholder='{"tracking_domain":"track.example.com"}'
            />
          </FilterField>
          <div className="flex flex-wrap items-center gap-3 sm:col-span-2">
            <FilterApplyButton
              disabled={patching || !draftPatchJson.trim()}
              onClick={onApplyPatch}
              type="button"
            >
              {patching ? 'Applying...' : 'Apply changes'}
            </FilterApplyButton>
            {patchSuccess ? (
              <p className="text-sm text-muted-foreground" role="status">
                Configuration updated.
              </p>
            ) : null}
          </div>
          {patchError ? (
            <div className="sm:col-span-2">
              <ErrorBlock title="Could not apply changes" message={patchError.message} />
            </div>
          ) : null}
        </FilterPanel>
      </PanelSection>

      <PanelSection title="Save configuration to disk">
        <FilterPanel className="rounded-none border-0 bg-transparent">
          <p className="text-sm text-muted-foreground sm:col-span-2">
            Persist the active configuration to disk. Leave the directory empty to use the server
            default install root.
          </p>
          <FilterField
            htmlFor="settings-install-root"
            label="Installation directory (optional)"
          >
            <Input
              id="settings-install-root"
              className="font-mono"
              value={draftInstallRoot}
              onChange={(event) => onDraftInstallRootChange(event.target.value)}
              placeholder="/opt/ad-event-processor"
            />
          </FilterField>
          <div className="flex flex-wrap items-center gap-3 sm:col-span-2">
            <PrimaryActionButton disabled={applying} loading={applying} onClick={onApplyToDisk} type="button">
              {applying ? 'Saving...' : 'Save to disk'}
            </PrimaryActionButton>
            {applySuccess && applyWrittenPath ? (
              <p className="text-sm text-muted-foreground" role="status">
                Saved to <span className="font-mono">{applyWrittenPath}</span>.
              </p>
            ) : null}
          </div>
          {applyError ? (
            <div className="sm:col-span-2">
              <ErrorBlock title="Could not save to disk" message={applyError.message} />
            </div>
          ) : null}
        </FilterPanel>
      </PanelSection>

      {error && hasSnapshot ? <ErrorBlock title="Refresh failed" message={error.message} /> : null}
    </PageChrome>
  );
}
