import type { ComponentProps, ReactNode } from 'react';
import { ArrowDown, ArrowUp, ArrowUpDown } from 'lucide-react';

import {
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { cn } from '@/lib/utils';

export type DirectoryTableProps = {
  children: ReactNode;
  className?: string;
  scrollable?: boolean;
};

export function DirectoryTable({ children, className, scrollable = false }: DirectoryTableProps) {
  return (
    <div className={cn('overflow-hidden rounded-2xl border border-border/40 bg-card/40', className)}>
      <div
        className={cn(
          'relative w-full min-w-0 max-w-full',
          scrollable
            ? 'ui-scrollbar max-h-[min(70vh,48rem)] overflow-auto'
            : 'overflow-x-auto',
        )}
      >
        <table className="w-full caption-bottom text-sm">{children}</table>
      </div>
    </div>
  );
}

export { TableBody, TableCell, TableHeader, TableRow };

export function DirectoryTableHead({
  className,
  ...props
}: ComponentProps<typeof TableHead>) {
  return <TableHead className={cn('h-10 bg-card/90 backdrop-blur-sm', className)} {...props} />;
}

export type SortableTableHeadProps = {
  label: string;
  sortField: string;
  activeSort: string;
  activeOrder: 'asc' | 'desc';
  onSort: (field: string) => void;
  className?: string;
  numeric?: boolean;
};

export function SortableTableHead({
  label,
  sortField,
  activeSort,
  activeOrder,
  onSort,
  className,
  numeric = false,
}: SortableTableHeadProps) {
  const active = activeSort === sortField;
  const Icon = active ? (activeOrder === 'asc' ? ArrowUp : ArrowDown) : ArrowUpDown;

  return (
    <DirectoryTableHead className={cn(numeric && 'text-right', className)}>
      <button
        className={cn(
          'inline-flex items-center gap-1 font-medium text-muted-foreground transition-colors hover:text-foreground',
          numeric && 'ml-auto',
          active && 'text-foreground',
        )}
        onClick={() => onSort(sortField)}
        type="button"
      >
        {label}
        <Icon aria-hidden className="h-3.5 w-3.5 shrink-0 opacity-70" />
      </button>
    </DirectoryTableHead>
  );
}
