import { useEffect, useMemo, useState } from 'react';
import { NavLink, Outlet } from 'react-router-dom';
import { PanelLeftClose, PanelLeftOpen, Search } from 'lucide-react';

import { BreadcrumbProvider } from '@/components/system/breadcrumb_context';
import { PageBreadcrumbs } from '@/components/system/page_breadcrumbs';
import { CommandPalette } from '@/components/system/command_palette';
import { EulaGate } from '@/components/system/eula_gate';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Toaster } from '@/components/ui/sonner';
import { TooltipProvider } from '@/components/ui/tooltip';
import { useSession } from '@/hooks/use_session';
import { filterNavGroups, NAV_GROUPS, type NavGroup, type NavItem } from '@/lib/nav_config';
import { hasAnyPortalAccess } from '@/lib/portal_access';
import { cn } from '@/lib/utils';

const SIDEBAR_COLLAPSED_KEY = 'aed-sidebar-collapsed';

function filterGroupsForPortals(groups: NavGroup[], permissions: string[] | undefined): NavGroup[] {
  return groups.map((group) => ({
    ...group,
    items: group.items.filter(
      (item) => item.path !== '/portals' || hasAnyPortalAccess(permissions),
    ),
  }));
}

function matchesNavQuery(item: NavItem, query: string): boolean {
  if (!query) {
    return true;
  }
  const haystack = `${item.label} ${item.path}`.toLowerCase();
  return haystack.includes(query);
}

export function AppShell() {
  const { session, user } = useSession();
  const [navQuery, setNavQuery] = useState('');
  const [collapsed, setCollapsed] = useState(false);

  useEffect(() => {
    try {
      setCollapsed(window.localStorage.getItem(SIDEBAR_COLLAPSED_KEY) === '1');
    } catch {
      setCollapsed(false);
    }
  }, []);

  const toggleCollapsed = () => {
    setCollapsed((value) => {
      const next = !value;
      try {
        window.localStorage.setItem(SIDEBAR_COLLAPSED_KEY, next ? '1' : '0');
      } catch {
        // ignore storage errors
      }
      return next;
    });
  };

  const navGroups = useMemo(() => {
    const filtered = filterNavGroups(NAV_GROUPS, user?.permissions);
    const withPortals = filterGroupsForPortals(filtered, user?.permissions);
    const query = navQuery.trim().toLowerCase();
    if (!query) {
      return withPortals;
    }
    return withPortals
      .map((group) => ({
        ...group,
        items: group.items.filter((item) => matchesNavQuery(item, query)),
      }))
      .filter((group) => group.items.length > 0);
  }, [navQuery, user?.permissions]);

  return (
    <EulaGate>
      <TooltipProvider>
        <CommandPalette />
        <Toaster />
        <a
          className="sr-only focus:not-sr-only focus:absolute focus:left-4 focus:top-4 focus:z-50 focus:rounded-md focus:bg-primary focus:px-3 focus:py-2 focus:text-sm focus:text-primary-foreground"
          href="#main-content"
        >
          Skip to content
        </a>
        <div className="flex h-screen overflow-hidden bg-background">
          <aside
            className={cn(
              'flex h-full shrink-0 flex-col bg-card/60 motion-safe:transition-[width] motion-safe:duration-200',
              collapsed ? 'w-14' : 'w-56',
            )}
          >
            <div
              className={cn(
                'flex shrink-0 items-center gap-2 p-4 pb-2',
                collapsed ? 'justify-center px-2' : 'justify-between',
              )}
            >
              {!collapsed ? (
                <p className="text-sm font-semibold">ad-event-processor</p>
              ) : (
                <span className="text-xs font-semibold" title="ad-event-processor">
                  aed
                </span>
              )}
              <Button
                aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
                className="h-8 w-8 shrink-0 p-0"
                onClick={toggleCollapsed}
                type="button"
                variant="ghost"
              >
                {collapsed ? (
                  <PanelLeftOpen className="h-4 w-4" />
                ) : (
                  <PanelLeftClose className="h-4 w-4" />
                )}
              </Button>
            </div>

            {!collapsed ? (
              <div className="shrink-0 px-4 pb-2">
                <div className="relative">
                  <Search className="pointer-events-none absolute left-2.5 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                  <Input
                    aria-label="Filter navigation"
                    className="h-9 pl-8 text-sm"
                    placeholder="Filter nav…"
                    value={navQuery}
                    onChange={(event) => setNavQuery(event.target.value)}
                  />
                </div>
              </div>
            ) : null}

            <nav
              aria-label="Main"
              className="ui-scrollbar min-h-0 flex-1 overflow-y-auto px-2 py-2 text-sm"
            >
              <div className="flex flex-col gap-4">
                {navGroups.map((group) => (
                  <div key={group.id} className="flex flex-col gap-1">
                    {!collapsed ? (
                      <p className="px-3 text-xs font-medium uppercase tracking-wide text-muted-foreground">
                        {group.label}
                      </p>
                    ) : null}
                    {group.items.map((item) => (
                      <NavLink
                        key={item.path}
                        title={collapsed ? item.label : undefined}
                        to={item.path}
                        className={({ isActive }) =>
                          cn(
                            'rounded-full px-3 py-2 transition-colors',
                            collapsed && 'px-2 text-center text-xs font-medium',
                            isActive
                              ? 'bg-secondary font-medium text-foreground'
                              : 'text-muted-foreground hover:bg-muted/60 hover:text-foreground',
                          )
                        }
                      >
                        {collapsed ? item.label.slice(0, 1) : item.label}
                      </NavLink>
                    ))}
                  </div>
                ))}
                <div className="flex flex-col gap-1">
                  {!collapsed ? (
                    <p className="px-3 text-xs font-medium uppercase tracking-wide text-muted-foreground">
                      Help
                    </p>
                  ) : null}
                  <NavLink
                    end={false}
                    title={collapsed ? 'Documentation' : undefined}
                    to="/docs"
                    className={({ isActive }) =>
                      cn(
                        'rounded-full py-2 transition-colors',
                        collapsed ? 'px-2 text-center text-xs' : 'px-3',
                        isActive
                          ? 'bg-secondary font-medium text-foreground'
                          : 'text-muted-foreground hover:bg-muted/60 hover:text-foreground',
                      )
                    }
                  >
                    {collapsed ? 'D' : 'Documentation'}
                  </NavLink>
                </div>
              </div>
            </nav>

            <div
              className={cn(
                'shrink-0 border-t border-border/40 p-4 text-xs text-muted-foreground',
                collapsed && 'px-2 text-center',
              )}
            >
              {session ? (
                <>
                  {!collapsed && session.role ? (
                    <p className="font-medium capitalize">{session.role}</p>
                  ) : null}
                  {!collapsed && session.timezone ? <p>{session.timezone}</p> : null}
                  <p className={cn('text-muted-foreground/80', !collapsed && 'mt-2')}>
                    {collapsed ? '⌘K' : 'Search pages… ⌘K'}
                  </p>
                </>
              ) : null}
            </div>
          </aside>

          <main
            className="ui-scrollbar min-h-0 min-w-0 flex-1 overflow-x-hidden overflow-y-auto"
            id="main-content"
            tabIndex={-1}
          >
            <BreadcrumbProvider>
              <div className="min-w-0 max-w-full p-6 lg:p-8">
                <PageBreadcrumbs />
                <Outlet />
              </div>
            </BreadcrumbProvider>
          </main>
        </div>
      </TooltipProvider>
    </EulaGate>
  );
}
