import { Moon, Sun } from 'lucide-react';

import { FilterPanel } from '@/components/system/filter_panel';
import { PanelSection } from '@/components/system/stat_panel';
import { Button } from '@/components/ui/button';
import { themeToggleLabel } from '@/lib/theme';
import { cn } from '@/lib/utils';
import { useTheme } from '@/providers/theme_provider';

function ThemeIcon({ theme }: { theme: 'light' | 'dark' }) {
  const showSun = theme === 'light';

  return (
    <span aria-hidden="true" className="relative inline-flex h-4 w-4 shrink-0">
      <Sun
        className={cn(
          'absolute inset-0 h-4 w-4 motion-safe:transition-all motion-safe:duration-300 motion-safe:ease-out',
          showSun
            ? 'rotate-0 scale-100 opacity-100'
            : 'rotate-90 scale-75 opacity-0',
        )}
      />
      <Moon
        className={cn(
          'absolute inset-0 h-4 w-4 motion-safe:transition-all motion-safe:duration-300 motion-safe:ease-out',
          showSun
            ? '-rotate-90 scale-75 opacity-0'
            : 'rotate-0 scale-100 opacity-100',
        )}
      />
    </span>
  );
}

export function SettingsAppearancePanel() {
  const { theme, setTheme } = useTheme();
  const nextTheme = theme === 'dark' ? 'light' : 'dark';

  return (
    <PanelSection title="Appearance">
      <FilterPanel className="rounded-none border-0 bg-transparent">
        <p className="text-sm text-muted-foreground sm:col-span-2">
          Choose how the admin UI is rendered on this device. The choice is remembered across
          sessions and page navigation.
        </p>
        <div className="sm:col-span-2">
          <Button
            aria-label={themeToggleLabel(theme)}
            className="gap-2"
            onClick={() => setTheme(nextTheme)}
            type="button"
            variant="outline"
          >
            <ThemeIcon theme={theme} />
            <span>{theme === 'dark' ? 'Dark theme' : 'Light theme'}</span>
          </Button>
        </div>
      </FilterPanel>
    </PanelSection>
  );
}
